import{s as e}from"./motion-Dx2kiXSB.js";import{t}from"./SEO-xwtpdIte.js";var n=e(),r={privacy:{title:`Privacy Policy`,seo:`Privacy Policy – KINTOX`,sections:[{h:`Information We Collect`,p:`We collect information you provide directly, such as your name, email address, and project details when you contact us or place an order. We also automatically collect certain technical data, including IP address, browser type, and usage patterns, to improve our services.`},{h:`How We Use Your Information`,p:`Your information is used to deliver our design services, process payments, communicate with you about your projects, and send occasional updates with your consent. We never sell your personal data to third parties.`},{h:`Data Protection`,p:`We implement industry-standard security measures including encryption, secure servers, and restricted access to protect your personal information. However, no method of transmission over the Internet is 100% secure.`},{h:`Cookies`,p:`We use essential cookies for site functionality and analytics cookies to understand usage patterns. You can control cookie preferences through your browser settings.`},{h:`Contact`,p:`For privacy-related inquiries, contact us at hello@kintox.design or through our contact form.`}]},terms:{title:`Terms of Service`,seo:`Terms of Service – KINTOX`,sections:[{h:`Services`,p:`KINTOX provides premium graphic design services including but not limited to UI/UX design, branding, social media graphics, and motion design. All services are delivered digitally unless otherwise agreed.`},{h:`Intellectual Property`,p:`Upon full payment, you receive full ownership rights to the final deliverables. KINTOX retains the right to display completed work in its portfolio unless a non-disclosure agreement is in place.`},{h:`Revisions`,p:`Each package includes a specified number of revision rounds. Additional revisions may be charged at our standard hourly rate. Revision requests must be submitted in writing.`},{h:`Payment Terms`,p:`Payments are processed through our secure checkout system. All prices are in INR and include applicable taxes. Full payment is required before final file delivery.`},{h:`Limitation of Liability`,p:`KINTOX shall not be liable for any indirect, incidental, or consequential damages arising from the use of our services. Our total liability is limited to the amount paid for the specific service.`}]},faq:{title:`Frequently Asked Questions`,seo:`FAQ – KINTOX`,sections:[{h:`How long does a typical project take?`,p:`Timelines vary by project complexity. A standard website UI takes 3–5 business days, while a full brand identity package may take 7–10 business days. Custom timelines are discussed during onboarding.`},{h:`What file formats will I receive?`,p:`You receive source files (.fig, .ai, .psd) along with export-ready formats (PNG, SVG, PDF, JPG) depending on the project type. All files are delivered via a shared drive link.`},{h:`Can I request revisions after delivery?`,p:`Each package includes specific revision rounds. Post-delivery revisions can be purchased separately. We recommend reviewing all deliverables thoroughly during the revision phase.`},{h:`Do you offer rush delivery?`,p:`Yes, rush delivery is available at an additional cost. Contact us with your deadline and we will provide a quote.`},{h:`What if I am not satisfied with the design?`,p:`We offer free revisions within your package scope. If you remain unsatisfied, we will work with you to refine the design until it meets your expectations. Refund policy applies as outlined in our terms.`}]},refund:{title:`Refund Policy`,seo:`Refund Policy – KINTOX`,sections:[{h:`30-Day Satisfaction Guarantee`,p:`We stand behind our work. If you are not satisfied with the initial concepts and we cannot revise them to meet your requirements, you may request a full refund within 30 days of the initial payment.`},{h:`Partial Refunds`,p:`Once revision work has begun beyond the initial concepts, a partial refund may be issued based on the percentage of work completed. Our standard rate is used to calculate completed work value.`},{h:`Non-Refundable Items`,p:`Rush delivery fees, third-party asset costs (fonts, stock images, licenses), and setup fees are non-refundable once the work has commenced.`},{h:`How to Request a Refund`,p:`Email us at hello@kintox.design with your order number and reason for the request. We respond within 48 hours and process approved refunds within 5–7 business days.`},{h:`Dispute Resolution`,p:`If you believe a refund is warranted under circumstances not covered here, please contact us directly. We are committed to fair resolutions and customer satisfaction.`}]}};function i({pageKey:e}){let i=r[e];return i?(0,n.jsxs)(`div`,{className:`min-h-screen bg-white`,children:[(0,n.jsx)(t,{title:i.seo}),(0,n.jsxs)(`div`,{className:`max-w-[700px] mx-auto px-6 py-20 md:py-28`,children:[(0,n.jsx)(`h1`,{className:`text-4xl md:text-5xl font-bold text-[#1D1D1F] tracking-[-0.03em] mb-10`,children:i.title}),(0,n.jsx)(`div`,{className:`space-y-10`,children:i.sections.map((e,t)=>(0,n.jsxs)(`div`,{children:[(0,n.jsx)(`h2`,{className:`text-lg font-semibold text-[#1D1D1F] mb-2`,children:e.h}),(0,n.jsx)(`p`,{className:`text-[15px] text-[#6E6E73] leading-relaxed`,children:e.p})]},t))})]})]}):null}export{i as default};